INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000838', 'Benarkah EOR bertujuan menurunkan saturasi minyak sisa (Sor) yang tidak dapat diproduksi oleh waterflood?', 'Is it true that EOR aims to reduce the residual oil saturation (Sor) that cannot be produced by waterflooding?', 'yesorno', 'PFC000000008', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
